import sys

def min_cost_to_complete_tasks():
    A = list(map(int, input().split()))

    dp = [float('inf')] * 4
    dp[0] = 0

    for i in range(1, 4):
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + abs(A[i-1] - A[j]))

    return dp[3]

if __name__ == "__main__":
    print(min_cost_to_complete_tasks())

